import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        ArrayList<Integer> scores = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) {
            scores.add(sc.nextInt());
        }

        int total = 0;
        int best = scores.get(0);
        int passCount = 0;
        for (int i = 0; i < n; i++) {
            int s = scores.get(i);
            total = total + s;
            if (s > best) {
                best = s;
            }
            if (s >= 60) {
                passCount = passCount + 1;
            }
        }

        int avg10 = total * 10 / n;
        System.out.println("平均 " + (avg10 / 10) + "." + (avg10 % 10) + " 分");
        System.out.println("最高 " + best + " 分");
        System.out.println("及格 " + passCount + " 人");
    }
}

